"Abstand Anfang / Ende":"المسافة من البداية / النهاية",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"المسافة من البداية / النهاية تحوّل الشفة إلى شفة جزئية. أما المقاطع المغلقة الأخرى في الرسم التخطيطي فتصبح فتحات في اللوح. الثقوب والنوافذ في الشفة: المركز على امتداد الحافة (وعلى امتداد القوس في الحافة المنحنية)، المركز من نهاية الثني، الحجم – وتظهر أيضاً في الشكل المفرود. وإذا انتقلت حافة منحنية إلى الحافة المجاورة لها دون زاوية، وكانت لكل منهما شفة بزاوية ثني متساوية، تمتد الشفتان إحداهما في الأخرى دون قطع تفريج. “كفاف من رسم تخطيطي” يقطع المقاطع المغلقة لرسم تخطيطي من الشفة: يمتد محور X على امتداد الحافة، ومحور Y باتجاه داخل الشفة، وتقع نقطة الصفر عند بداية الحافة على نهاية الثني (قابلة للإزاحة).",
