"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"حدّد كل الأوجه التي يجب أن تختفي (في الجيب الجدران والقاع، في الثقب الجدار، في التدوير السطح المدور). تُمدَّد الأوجه المجاورة عبر الفجوة. تُعاد حسابات الخطوة عند تعديل الجسم؛ وفي المرة الأولى تُحمَّل لذلك نواة الهندسة الكاملة (بضع ثوانٍ).",
