"Das Ergebnis des Geometriekerns ist unlesbar":"نتيجة نواة الهندسة غير قابلة للقراءة",
"Das Ergebnis konnte nicht geschrieben werden":"تعذّرت كتابة النتيجة",
"Das Maß muss größer als 0 sein.":"يجب أن يكون البُعد أكبر من 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"تبقى الشبكة شبكة مثلثات (ليست B-Rep). التحرير ضمن الشبكة: إصلاح، تقليل، تنعيم، قطع بمستوى … يمكن لاستراتيجيات التفريز ثلاثية الأبعاد في التصنيع معالجتها مباشرة.",
"Das Netz hat {0} Dreiecke. Jedes wird eine Fläche des Körpers – das dauert lange und macht den Körper träge. Vorher „Reduzieren“ ist meist besser.\n\nTrotzdem umwandeln?":"تحتوي الشبكة على {0} مثلث. يصبح كل منها وجهاً في الجسم – وهذا يستغرق وقتاً طويلاً ويجعل الجسم بطيئاً. من الأفضل عادةً تنفيذ “تقليل” قبل ذلك.\n\nهل تريد التحويل رغم ذلك؟",
"Das Netz ist nicht geschlossen. Zuerst „Reparieren“ ausführen – ein Körper braucht eine geschlossene Hülle.":"الشبكة غير مغلقة. نفّذ “إصلاح” أولاً – فالجسم يحتاج إلى غلاف مغلق.",
"Das Netz reicht in Z von {0} bis {1} mm, in X von {2} bis {3} mm, in Y von {4} bis {5} mm. Punkte, die weniger als die Toleranz von einer Geraden abweichen, entfallen.":"تمتد الشبكة في Z من {0} إلى {1} mm، وفي X من {2} إلى {3} mm، وفي Y من {4} إلى {5} mm. تُحذف النقاط التي تنحرف عن الخط المستقيم بأقل من السماحية.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"يجب ألا يقطع المقطع المحور. يمكن لخط مفتوح في الرسم التخطيطي أن يكون المحور.",
"Das Profil mit den jetzigen Werten überschreiben":"استبدال الملف الشخصي بالقيم الحالية",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"يُسحب المقطع على امتداد خط/خط متعدد المقاطع. الأفضل رسم المقطع عموديًا على بداية المسار (مثل المقطع على XZ والمسار على XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"يُنقش المقطع بارزًا أو غائرًا ابتداءً من مستوى الرسم التخطيطي.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"الخامة هي متوازي المستطيلات حول الجسم المحدد (مع الإزاحة).",
"Das Setup hat keine Operationen.":"لا يحتوي الإعداد على عمليات.",
"Das Teil ist für die Senkung zu dünn (Senktiefe {0} mm, Dicke {1} mm).":"الجزء رقيق جداً للتغطيس (عمق التغطيس {0} mm، السماكة {1} mm).",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"تفرّز الأداة في دوائر يتحرك مركزها على امتداد المجرى. ولا تكون أبدًا متعشقة بعرضها الكامل – وهذا يتيح أعماق تغذية كبيرة ويحمي القاطع والمغزل. ينبغي أن يكون القاطع بنحو 60 % من عرض المجرى.",
"Das Werkzeug schneidet die Fläche nicht":"الأداة لا تقطع السطح",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"تقطع الأداة باتجاه الأوجه المحددة حتى تبلغ سماحيات التشغيل المحددة.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"تغوص الأداة عموديًا كالمثقاب، صفًا بصف، حتى النموذج مع السماحية. تعمل قوة القطع على امتداد المغزل: مناسب للأدوات الطويلة والتجاويف العميقة والآلات قليلة الصلابة. يجب أن تقطع الأداة عند المركز.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"تتجنب الأداة هذه الأوجه مع مراعاة مسافات الأمان المحددة (المشابك، المنجلة).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"تتجنب الأداة هذه الأوجه أثناء تشغيل الأوجه القريبة منها، وتلتزم بمسافات الأمان.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"الضغطة الأولى على Esc تلغي الأداة أو التحديد فقط – ضغطة Esc زائدة لا تغلق الرسم التخطيطي",
"Das ist eine runde Fläche – bitte eine ebene Fläche anklicken.":"هذا وجه مستدير – يُرجى النقر على وجه مستوٍ.",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"هذا ليس ثقبًا (تدوير أو نتوء) – يُرجى النقر على الجدار الداخلي لثقب.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"هذا ليس ثقبًا (سطحًا أسطوانيًا) – يُرجى النقر على جدار الثقب.",
"Das ist keine WerkFab-Design-Datei.":"هذا ليس ملف تصميم WerkFab.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"هذه ليست حافة مائلة – انقر على طرفي حافة الشطف.",
"Datei":"ملف",
"Datei ist keine WerkFab-Einstellungsdatei.":"الملف ليس ملف إعدادات WerkFab.",
"Datei konnte nicht geöffnet werden:":"تعذر فتح الملف:",
"Dateiendung":"امتداد الملف",
