"Drehen: Drehpunkt anklicken, dann den Winkel mit der Maus zeigen (Vorschau). Esc beendet.":"دوران: انقر على نقطة الدوران ثم حدد الزاوية بالفأرة (معاينة). Esc للإنهاء.",
"Drehen: Durchmesser, auf dem der Revolver schaltet (Okuma, LinuxCNC). 0 = Rohteil-Ø + 200 mm":"الخراطة: القطر الذي يدور عنده البرج (Okuma، LinuxCNC). 0 = Ø الخامة + 200 mm",
"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"تدوير: اختر العناصر ثم انقر على نقطة الدوران وحدّد الزاوية بالفأرة (معاينة)؛ ويمكن أيضاً كنسخة",
