"Drehen: Polar-Interpolation ein (X Durchmesser, C in mm; leer = X/C in Grad)":"الخراطة: تشغيل الاستيفاء القطبي (X قطر، C بالمم؛ فارغ = X/C بالدرجات)",
"Drehen: Schlichtzyklus (Kontur des Schruppzyklus)":"الخراطة: دورة التشطيب (كفاف دورة التخشين)",
