"Drehen: Winkel (°, gegen den Uhrzeigersinn); Drehpunkt X; Drehpunkt Y; Kopien (0 = drehen)":"دوران: الزاوية (°، عكس اتجاه عقارب الساعة)؛ نقطة الدوران X؛ نقطة الدوران Y؛ النسخ (0 = دوران)",
