"Drehen: Y-Achse ein (Ebene X/Y; hier auch die C-Klemmung der Maschine eintragen)":"الخراطة: تشغيل المحور Y (المستوى X/Y؛ أدخل هنا أيضًا أمر تثبيت C الخاص بالآلة)",
"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"الخراطة: Z أمام الوجه المستوي الذي يدور عنده البرج. 0 = مسافة الأمان + 100 mm",
"Drehen: Zylinder-Interpolation aus":"الخراطة: إيقاف الاستيفاء الأسطواني",
