"Drehmaschine mit Y-Achse: Schlüsselflächen, Konturen und Taschen auf der Planfläche fahren mit feststehendem Teil (C fest) in X und Y – genauer als die Polar-Interpolation. Was über den Y-Weg hinausgeht, bleibt bei der Polar-Interpolation.":"مخرطة ذات محور Y: تُنفَّذ الأسطح المفتاحية والكفافات والجيوب على الوجه الأمامي والقطعة ثابتة (C مثبَّت) في X وY – بدقة أعلى من الاستيفاء القطبي. أما ما يتجاوز مشوار Y فيبقى بالاستيفاء القطبي.",
