"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}) – der Rand reißt dabei meist ein.":"الياقة {0}: يُوسَّع الثقب التمهيدي Ø {1} mm إلى Ø {2} mm (المعامل {3}) – وغالباً ما يتشقق الحرف عندها.",
