"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"الياقة {0}: مرتفعة جداً لهذا الثقب (سيبقى الثقب التمهيدي بلا قطر)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"الياقة: يُسحب حرف الثقب الدائري إلى الأعلى ليصبح طوقاً، مثلاً كياقة للسنون اللولبية. قطر الثقب في الرسم التخطيطي هو القطر الداخلي النهائي؛ وفي القَصّ يُقطع الثقب التمهيدي الأصغر.",
