"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"اختصارات مخصصة: افتح قائمة المجموعة (▾) في شريط الأدوات، وانقر على ⋮ بجانب الأمر ← «تغيير اختصار لوحة المفاتيح …».",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"يمكن سحب الأبعاد والملاحظات المخصصة في الورقة بالفأرة (مسافة خط البُعد، زاوية خط الإشارة، نصف قطر قوس الزاوية). النقر على زاويتين = بُعد طولي. النقر على حافة دائرة في المنظر العلوي = القطر (أو نصف القطر). الزاوية: الرأس أولًا، ثم نقطة على كل ضلع. الشطف: طرفا الحافة المائلة – يعطي مثلًا 2×45°. في حقل النص بعد كل بُعد توجد إضافة مثل ±0,1 أو H7 أو 4×.",
