"Erhebung braucht zwei Skizzen mit geschlossenen Profilen auf verschiedenen Ebenen.":"Loft يحتاج إلى رسمين تخطيطيين بمقطعين مغلقين على مستويين مختلفين.",
"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"Loft يحتاج إلى رسمين تخطيطيين بمنحنى واحد في كل منهما (على مستويين مختلفين).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"تعذر التحويل السطحي (Loft) – تحقق من المقاطع العرضية (مقطع مغلق واحد لكل منها، دون التواء)",
"Erhebung nicht möglich – je Skizze eine Kurve, gleiche Richtung, nicht verdreht":"تعذر التحويل السطحي (Loft) – منحنى واحد لكل رسم تخطيطي، بنفس الاتجاه ودون التواء",
"Ersetzt den Standard-Kurzbefehl „{0}“.":"يستبدل الاختصار الافتراضي “{0}”.",
"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"انقر أولًا على الوجه في الجسم الذي سيتحرك، ثم على الوجه الهدف في الجسم الآخر. يُدوَّر الجسم ويُزاح حتى تقع نقطة النقر الأولى على الثانية ويستقر الوجهان أحدهما على الآخر.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"انقر أولًا على الحافة في الجسم الذي سيتحرك، ثم على الحافة الهدف في الجسم الآخر. تتطابق الحواف المستقيمة (المنتصف على المنتصف)؛ وفي الحواف الدائرية – الثقب والنتوء – تُحاذى المحاور في الاتجاه نفسه وتُطابق المراكز.",
"Erst ein Setup anlegen.":"أنشئ إعدادًا أولًا.",
"Erst ein Setup mit Operationen anlegen.":"أنشئ أولًا إعدادًا يحتوي على عمليات.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"اختر أولاً رسماً تخطيطياً أو مستوى إنشاء – عندها يعرض Ctrl+8 المنظر عمودياً عليه.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"أنشئ أولًا جسمًا في التصميم أو أدرج شبكة (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"أنشئ جسمًا أولًا في التصميم.",
"Erst einen Namen für das Profil eingeben.":"أدخل اسماً للملف الشخصي أولاً.",
"Erst in eine Vorlage klicken, dann den Platzhalter wählen":"انقر أولًا داخل قالب، ثم اختر العنصر النائب",
"Erste Ecke klicken, dann gegenüberliegende Ecke.":"انقر على الزاوية الأولى ثم الزاوية المقابلة.",
