"Erstellt {0}":"تاريخ الإنشاء {0}",
"Ersten Bogenmittelpunkt, zweiten Bogenmittelpunkt, dann Breite klicken.":"انقر على مركز القوس الأول ثم مركز القوس الثاني ثم العرض.",
