"Fläche anklicken – die Bohrung entsteht mit":"انقر على وجه – يُنشأ الثقب معه",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"انقر على وجه: عند كل نقطة نقر يُنشأ ثقب العبور للبرغي (ISO 273، السلسلة المتوسطة) عبر جميع الأجزاء المتراكبة هناك – للبراغي المخروطية الرأس بتغطيس مخروطي 90°، وللبراغي الأسطوانية الرأس عند الرغبة بثقب مغطس (DIN 974-1، السلسلة 1) بعمق الرأس. ويستقر البرغي فيه مباشرة. ويمكن بعد ذلك تعديل الثقب والبرغي في الخط الزمني.",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"انقر على وجه جسم: تُضاف حدوده إلى الرسم التخطيطي ككفاف. النقر على حافة يسقط هذه الحافة فقط (تبقى الدوائر دوائر). الهندسة المسقطة بنفسجية اللون.",
"Fläche ersetzen":"استبدال وجه",
