"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"أوجه مسطحة عند طرف القطعة (وجهان، مربع، سداسي) بقاطع طرفي مُدار على امتداد Z. عرض المفتاح = ضعف بُعد الوجه عن محور الدوران. يتحرك X وC معًا (استيفاء قطبي، Fanuc G12.1)؛ وبدون هذا القالب في المعالج اللاحق تُخرَج خطوات X/C قصيرة.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"انقر على الأوجه المراد تثخينها (النقر مجددًا يزيل التحديد).",
"Flächen anklicken, die geneigt werden (erneut klicken entfernt).":"انقر على الأوجه المراد إمالتها (النقر مرة أخرى يزيلها).",
