"Flächen anklicken, die versetzt werden (erneut klicken entfernt).":"انقر على الأوجه المراد إزاحتها (النقر مجددًا يزيل التحديد).",
"Flächen im Modell":"الأوجه في النموذج",
"Flächen mit gemeinsamen Kanten werden zu einer verbunden. Ist die Hülle rundum geschlossen, entsteht ein Volumenkörper (danach normal weiterbearbeitbar). Lücken größer als die Toleranz bleiben offen.":"تُدمج الأسطح ذات الحواف المشتركة في سطح واحد. إذا كان الغلاف مغلقًا من كل الجهات ينتج جسم مصمت (يمكن تعديله بعد ذلك كالمعتاد). تبقى الفجوات الأكبر من التفاوت مفتوحة.",
