"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"يتتبع جميع الحواف الخارجية الحادة التي يمكن الوصول إليها من الأعلى ويكسرها بمقدار عمق إزالة النتوءات – بقاطع الشطف كشطف (محور الأداة عمودي، الرأس خارج الحافة)، وبقاطع كروي/لوليبوب مدوّرة.",
