"Gelenkursprung: Bohrung, Zapfen oder Fläche anklicken (mehrere nacheinander möglich).":"أصل المفصل: انقر على ثقب أو نتوء أو وجه (يمكن اختيار عدة عناصر تباعًا).",
"Gelenkursprünge ({0})":"أصول الوصلات ({0})",
