"Gemeinsame Schnittkanten nur einmal schneiden":"قص الحواف المشتركة مرة واحدة فقط",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"حواف القص المشتركة: إذا كانت قطعتا قص متباعدتين بمقدار عرض قطع واحد بالضبط (أدخل عرض القطع كمسافة عند الترتيب)، ينطبق مساراهما على الحافة المشتركة وتُقص مرة واحدة فقط. ولا يقع مدخل القطع أبداً في جزء مجاور: إذا لم يوجد بجانب الكفاف هدر حر، يتم الاختراق على الكفاف. بعد “معاينة” تعرض صورة لكل لوح المسار قبل حفظ الملفات.",
