"Geometriekern: OpenCascade (über replicad) · Darstellung: three.js · Einstellungen werden auf diesem Rechner gespeichert.":"نواة الهندسة: OpenCascade (عبر replicad) · العرض: three.js · تُحفظ الإعدادات على هذا الحاسوب.",
"Geometriekern: {0}":"نواة الهندسة: {0}",
"Georgia (Serifen)":"Georgia (بخطوط زخرفية)",
