"Gerade (radial)":"مستقيم (شعاعي)",
"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"الخطوط المستقيمة في الرسم التخطيطي التي لا تنتمي إلى أي مقطع (بما فيها الخطوط المساعدة). الثني: الخط هو منتصف منطقة الثني، والرسم التخطيطي هناك هو القَصّ – يبقى أكبر جزء من اللوح في مكانه، وكل ما يقع بعد الخط يدور مع شفاته. يسري الخط على اللوح بأكمله. ضلع التقوية: ضلع على امتداد الخط، مستدير في المقطع العرضي وعند الطرفين؛ وتحتفظ الصفيحة بسماكتها.",
