"Geschlossen (Gehrung)":"مغلق (قطع مائل)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"مغلق: تمتد الألسنة على حافتين متجاورتين حتى منصّف زاوية الركن وتترك الفجوة هناك. يقع تفريغ الزاوية حيث تتقاطع مناطق الثني – في الشكل المفرود وفي الجزء المثني. كما تُقص الشفة على حافة منحنية بزاوية مائلة (قطع مشطوف) عند ركن حقيقي (دون تفريغ للزاوية هناك).",
