"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"أول منحنى في كل رسم تخطيطي – مفتوحًا أو مغلقًا. تُوصل المنحنيات بغلاف (سطح بلا سماكة).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"ملف واحد لكل لوح. يسير المسار بجانب المحيط داخل الهالك بمسافة نصف عرض القطع (وفي الفرز نصف قطر الفريزة)؛ وتأتي الفتحات قبل محيط قطعتها، ويبدأ كل كفاف بمدخل قطع من الهالك. تُقطع شقوق التهوية على خطها. الجسور الماسكة: يبقى هذا العدد من المواضع لكل محيط دون قطع (ليزر، بلازما، نفث الماء: ينقطع الشعاع هناك؛ الفرز: ترتفع الفريزة إلى نصف سماكة الصفيحة)، والمحيطات التي يقل طولها عن 40 mm لا تحصل على أي جسر. يحدد «وحدة التحكم» كيفية تشغيل الشعاع وإيقافه؛ ويظهر زمن الاختراق في البرنامج بصيغة G4، إلا إذا كانت وحدة التحكم تخترق بنفسها. نقطة الصفر هي الزاوية السفلية اليسرى للوح، وفي الفرز يكون Z0 هو السطح العلوي للصفيحة. افحص البرنامج قبل استخدامه على الآلة أو في محاكي NC.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"كل محور على حدة: انقر على حافة أو ركن أو وجه أو ثقب. المحاور غير المعيّنة تؤخذ من نقطة الخامة.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"كل عملية كبرنامج فرعي (LBL) في نهاية البرنامج، ويُستدعى بـ CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"كل دائرة في الرسم التخطيطي هي مركز ثقب. يُحفر عكس عمودي الرسم التخطيطي (داخل المادة).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"تُكرَّر كل دائرة في الرسم التخطيطي بتدويرها حول المركز (بإحداثيات الرسم التخطيطي) – دائرة على مسافة نصف قطر دائرة الخطوة تعطي دائرة ثقوب.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"تتحول كل دائرة في الرسم التخطيطي إلى شبكة: المسافات في X وY للرسم التخطيطي (القيم السالبة مسموحة).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"الآن انقر على نقطة على الضلع الثاني.",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"حرّك الآن كل اتجاه مرة واحدة حتى النهاية: ادفع، اسحب، اضغط، أمِل، لف (10 s) …",
