"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"المعايرة: انقر على نقطتين في الصورة معروفة المسافة بينهما وأدخل المسافة الفعلية – تحصل الصورة على المقياس الصحيح.",
