"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"الحافة {0}: شفة على حافة منحنية – يُشدّ طرفها بنسبة {1} % أثناء التشكيل (خطر التشقق)؛ وقطعة القص هناك تقريبية.",
