"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"الحافة {0}: توجد فتحة على بعد {1} mm من الثني (أقل من 2 × سماكة الصفيحة) – وستتشوه عند الثني.",
