"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"اترك الغطاء واختر «معايرة نقطة الصفر». ثم جرّب كل اتجاه: يجب أن يتحرك الشريط وأن يبقى عند السكون داخل المنطقة الميتة الرمادية.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"دفع الغطاء = تحريك، ضغط/سحب = تكبير، إمالة ولف = تدوير النموذج. في الرسوم التخطيطية التحريك والتكبير فقط. SpaceMouse Pro/Enterprise: T, F, R = منظر علوي، أمامي، أيمن. إذا لم يحدث شيء: أغلق برنامج تشغيل 3Dconnexion لفترة وجيزة ثم أعد التوصيل.",
