"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"كفاف بـ {0} نقطة – Okuma: G85 (LAP) مع الكفاف G81…G80، Fanuc: G71 P…Q…. تقوم وحدة التحكم بالتخشين بتقسيمها الخاص؛ المحاكاة هنا هي مسار WerkFab.",
"Kontur zum Freifräsen davor anlegen":"إنشاء كفاف للتفريز الحر قبله",
