"Konturauswahl":"تحديد الكفاف",
"Konturen außen und innen":"الكفافات الخارجية والداخلية",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"تتبع الكفافات حافة المناطق الداكنة. ويمر الخط المركزي في منتصف الخطوط – مناسب للنقش والرسومات الخطية. يتعرف «خطوط مستقيمة وأقواس ودوائر» على الحواف المستقيمة والزوايا الحادة والتقوسات والدوائر؛ ويتبع «خطوط متعددة المقاطع» الصورة نقطة بنقطة. اضبط المقياس بعد ذلك عند الحاجة باستخدام «معايرة القالب» أو «تحجيم».",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"الكفافات ذات تعويض نصف القطر في وحدة التحكم (RL/RR) تُقترب وتُبتعد بـ APPR/DEP؛ وتحسب وحدة التحكم النقطة المساعدة والتعويض بنفسها",
