"Kurven":"المنحنيات",
"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"منحنيات رسم تخطيطي على السطح الأمامي (عموديًا على محور الدوران) بقاطع مُدار على امتداد Z (يتحرك X وC معًا؛ Fanuc: الاستيفاء القطبي G12.1). تُفرَّز المنحنيات المفتوحة ذهابًا وإيابًا. العمق ابتداءً من السطح الأمامي.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"تُلَفّ منحنيات رسم تخطيطي موضوع بمحاذاة محور الدوران على المحيط وتُفرَّز بقاطع مُدار موجّه نحو المحور (يتحرك Z وC معًا؛ Fanuc: الاستيفاء الأسطواني G7.1). يحدد مستوى الرسم الزاوية التي يقع عندها الكفاف؛ وتصبح القطع الأفقية في الرسم أقواسًا حول القطعة. العمق ابتداءً من القطر الخارجي.",
"Kurzbefehl":"الاختصار",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"تقطع الأداة المسارات القصيرة (حتى مسافة الإبقاء) في الأسفل بمعدل تغذية الانتقال بدلًا من المرور فوق ارتفاع الانسحاب – بدون فحص تصادم، لذا ينبغي إبقاؤها صغيرة.",
"KÖRPER":"الجسم",
"Körper":"الأجسام",
