"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"مع نقاط التحكم يمر نصف القطر عبر القيم المحددة (الموضع بنسبة % من طول الحافة). تتولى الحساب نواة الهندسة الكاملة؛ ويستغرق تحميلها بضع ثوانٍ في المرة الأولى.",
"Mit dem 3D-Taster kann nicht zerspant werden":"لا يمكن القطع بالمجس ثلاثي الأبعاد",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"المقارنة بالقطعة النهائية: أخضر = على المقاس، أزرق = مادة متبقية، أحمر = عميق جدًا",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"حرّك الفأرة بجوار كفاف (الجانب يحدد الاتجاه) · Esc للإنهاء",
"Mit diesem Werkzeug kann nicht gefräst werden":"لا يمكن التفريز بهذه الأداة",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"مع ذكر اللولبة استخدم دورة “ثقب لولبي” فقط – دورة الحفر ستكسره",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"مع عدة تغذيات يُفرَّز عمق السن على خطوات تزيل كل منها كمية متساوية تقريبًا – وهذا أرفق بقواطع السنون الصغيرة والمواد الصلبة. تعيد التمريرة الفارغة المسار الأخير مرة أخرى دون تغذية.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"عند تفعيل “دورات الحفر” في برنامج NC تُخرَج دورات التحكم (G81–G86، Heidenhain CYCL 200–207، Sinumerik CYCLE81–85)، وإلا تُخرَج الحركات مفصّلة.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"عند تفعيل “الاحتفاظ بالأصل” يصبح الأصل وصورته المنعكسة شبكة واحدة؛ وتُوصل النقاط الواقعة على مستوى الانعكاس – فيتحول النصف المفتوح إلى قطعة مغلقة.",
