"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"تشغيل ما تركته أداة فرز أكبر في الزوايا فقط.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"تتبّع فقط أجزاء الكفاف التي لم تصل إليها أداة فرز أكبر (الزوايا الداخلية، المناطق الضيقة). بدون أقواس دخول/خروج وجسور تثبيت وتمريرات تشطيب؛ التعويض في الحاسوب.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"فقط حيث لم تصل الأداة المرجعية: المناطق المسطحة بشكل متوازٍ، والمناطق الشديدة الانحدار كخط مائي. مع أداة من القائمة يُحتسب شكلها أيضًا – مثلًا ما يتركه قاطع ذو طرف دائري في التقعرات.",
"Nur ebene Flächen können als Skizzenebene dienen.":"لا يمكن استخدام إلا الأوجه المستوية كمستوى للرسم التخطيطي.",
