"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"الأوجه المستوية المتجهة للأعلى نحو الأداة فقط (أفقية في هذا الإعداد).",
"Nur für Außen-Drehmeißel":"لأدوات الخراطة الخارجية فقط",
