"Nut angetrieben (C-Achse)":"مجرى بأداة مدارة (المحور C)",
"Nut liegt nicht am Teil":"المجرى ليس على القطعة",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"مجرى على امتداد محور الدوران (مثل مجرى الخابور) بقاطع مُدار موجّه نحو المحور؛ يمسك المغزل الرئيسي القطعة كمحور C. عرض المجرى = قطر القاطع Ø. بداية/نهاية Z في Z النموذج؛ إذا وصل المجرى إلى السطح الأمامي يدخل القاطع من الأمام، وإلا يغوص عند البداية. العمق ابتداءً من القطر الخارجي.",
