"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"تُسحب المنحنيات المفتوحة أو المغلقة عموديًا على الرسم التخطيطي – ينتج سطح (جدار بلا سماكة). ومع «تثخين» أو «خياطة» يتحول إلى حجم.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"تُدوَّر المنحنيات المفتوحة أو المغلقة حول المحور – ينتج سطح وليس حجمًا.",
"Ohne Mutter":"بدون صامولة",
"Ohne eigene Taste gilt der Standard „{0}“.":"بدون مفتاح مخصص يُطبَّق الافتراضي “{0}”.",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"بدون «مُجسَّم» يُعرض السن للتمثيل فقط (سريع). عند التجسيم يُقطع شكل السن فعليًا، مثلًا للطباعة ثلاثية الأبعاد. ثقب M8 = Ø6,8.",
