"Okuma OSP-M Fräsen":"Okuma OSP-M فريزة",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: لا تنتقل G28/G53 هناك إلى إحداثيات الماكينة (G53 تلغي تصحيح طول الأداة) – التراجع إلى ارتفاع الأمان، ولم تُخرَج حركة مرجع XY",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: لم تُخرَج دالة تنعيم (G5.1 خاصة بـ Fanuc) – اضبط Hi-Cut/Super-NURBS على الماكينة",
"Okuma: Korrektur+Werkzeug+Schneide (z. B. 010101)":"Okuma: التصحيح+الأداة+حافة القطع (مثل 010101)",
