"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade: جميع الوظائف. نواة Rust (truck، تجريبية): الأجسام الأساسية، البثق، الدوران، الثقب، النمط، الانعكاس، النقل، تغيير المقياس، الدمج وتصدير STEP – تُوسَم الميزات الأخرى بـ «غير مدعومة بعد».",
