"Projizieren (J): Fläche oder Kante eines Körpers anklicken – ihr Abbild kommt in die Skizze":"إسقاط (J): انقر على وجه أو حافة جسم – يُضاف مسقطها إلى الرسم التخطيطي",
"Projizieren von Kanten und Flächen braucht einen Volumenkörper des Standardkerns – Körperumriss und Schnittkurven gehen auch bei Netzen.":"إسقاط الحواف والأوجه يحتاج إلى جسم صلب من النواة الافتراضية – حدود الجسم ومنحنيات التقاطع تعمل أيضًا مع الشبكات.",
"Projizieren: Fläche oder Kante eines Körpers anklicken.":"الإسقاط: انقر على وجه أو حافة لجسم.",
"Projizierte Fläche: folgt dem Körper, wenn er sich ändert.":"وجه مسقط: يتبع الجسم عند تغيره.",
"Projizierte Kante: folgt dem Körper, wenn er sich ändert.":"حافة مسقطة: تتبع الجسم عند تغيره.",
