"Prägen braucht einen Körper.":"النقش البارز يحتاج إلى جسم.",
"Prägung":"نقش بارز",
"Prägung {0}: die Kontur ist schmaler als 2 × Blechdicke – es bleibt kein Hohlraum.":"النقش البارز {0}: الكفاف أضيق من 2 × سماكة الصفيحة – لن يبقى تجويف.",
"Prägung {0}: lässt sich so nicht formen":"النقش البارز {0}: لا يمكن تشكيله هكذا",
"Prägung {0}: mit dieser Wandschräge lässt sie sich nicht formen":"النقش البارز {0}: لا يمكن تشكيله بهذا الميل للجدار",
"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"النقش البارز {0}: {1} mm أعلى من 3 × سماكة الصفيحة – مع جدار عمودي ستتمزق الصفيحة.",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt; das zweite Feld ist die Wandschräge (0° = senkrecht). Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"النقش البارز: لا يُقطع الكفاف بل يُدفع خارج اللوح بمقدار الارتفاع؛ والحقل الثاني هو ميل الجدار (0° = عمودي). الكبسة الغاطسة: يُكبس حرف الثقب الدائري ليصبح مخروطاً بزاوية 90° – للبراغي المخروطية الرأس في الصفائح الرقيقة (− للأسفل: البرغي من الأعلى).",
