"Tasche Planfläche (C-Achse)":"جيب على الوجه الأمامي (المحور C)",
"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"جيب على المحيط الخارجي من الكفافات المغلقة لرسم تخطيطي يقع بمحاذاة محور الدوران (تبقى الكفافات الداخلية كجزر). يُلَفّ الرسم التخطيطي على القطر؛ وتقوم مطحنة طرفية مسطحة مدارة موجهة نحو المحور بالإزالة من الداخل إلى الخارج (يتحرك Z وC معًا؛ في Fanuc: الاستيفاء الأسطواني G7.1). تغوص القاطعة على مسار منحدر على امتداد الحلقة الأعمق.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"جيب في السطح الأمامي من الكفافات المغلقة لرسم تخطيطي (تبقى الكفافات الداخلية كجزر)، بقاطع طرفي مُدار على امتداد Z. يتم التفريغ من الداخل إلى الخارج؛ يغوص القاطع على منحدر على امتداد أعمق مسار ويبقى للأسفل ضمن المستوى الواحد. يتحرك X وC معًا (Fanuc: الاستيفاء القطبي G12.1). العمق ابتداءً من السطح الأمامي.",
