"Teilt Kanten, die länger sind, in der Mitte (je Durchgang einmal) – die Form bleibt gleich. 0 teilt jede Kante: jedes Dreieck wird zu vier. Sinnvoll vor dem Glätten grober Netze.":"يقسم الحواف الأطول عند المنتصف (مرة واحدة في كل تمريرة) – ويبقى الشكل كما هو. القيمة 0 تقسم كل حافة: يصبح كل مثلث أربعة مثلثات. مفيد قبل تنعيم الشبكات الخشنة.",
