"Verbindet doppelte Punkte, entfernt entartete und doppelte Dreiecke, dreht falsch herum liegende Dreiecke und schließt Löcher.":"يدمج النقاط المكررة، ويزيل المثلثات المتحللة والمكررة، ويقلب المثلثات ذات الاتجاه الخاطئ، ويسد الثقوب.",
