"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"تجري عملية حقيقية بين شبكتين مغلقتين: تختفي الأوجه الداخلية وتُعاد تشبيك حواف التقاطع. ويقتصر الحساب على المنطقة التي يمكن أن تلتقي فيها الشبكتان – لذا تكون العملية سريعة لشبكة كبيرة مع تدخل صغير. إذا تداخلت شبكتان كبيرتان بالكامل، فنفّذ “تقليل” قبل ذلك.",
