"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"وصلة براغي: تُدرج الورود والصامولة مع البرغي دفعة واحدة في كل ثقب يُنقر عليه. سماكة الشد هي طول الثقب – عبر عدة أجزاء إذا كانت ثقوبها متحاذية ومتلاصقة. عند استخدام الصامولة يُقترح أقصر طول مفضل يبرز عنده البرغي من الصامولة بمقدار خطوتي سنّ.",
