"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"يلف منحنيات الرسم على الأسطوانة: يبقى X كما هو، وتصبح المسافة عموديًا على المحور قوسًا على قطر الفرد Ø (الدوران A). يجب أن يكون الرسم موازيًا للمحور A، مثلًا على مستوى مماسّ. يتم التفريز بعمق ثابت تحت سطح القطعة – للنقش والكتابة والمجاري حول القطعة.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"مثل كفاف ثلاثي الأبعاد، لكن الأداة تنزل باستمرار دون درجات – بلا آثار غوص على الجدران الشديدة الانحدار.",
