"{0}: Nullpunkt Y/Z liegt nicht auf der Drehachse A (Achse bei Y{1} Z{2}) – für 4-Achs-Simultan den Nullpunkt auf die Achse legen (Rohteil-Punkt Mitte Y/Z)":"{0}: نقطة الصفر Y/Z ليست على محور الدوران A (المحور عند Y{1} Z{2}) – لتشغيل 4 محاور متزامنة ضع نقطة الصفر على المحور (نقطة الخامة: منتصف Y/Z)",
"{0}: Postprozessor ohne Drehzyklus – als Bahn ausgegeben":"{0}: المعالج اللاحق دون دورة خراطة – أُخرج كمسار",
"{0}: Postprozessor ohne Polar-Interpolation – Flächen als kurze X/C-Schritte (C in Grad) ausgegeben; der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Polar-Interpolation ein/aus“ eintragen":"{0}: معالج لاحق بدون استكمال قطبي – أُخرجت الأوجه كخطوات قصيرة X/C (C بالدرجات)؛ وعندئذ، حسب وحدة التحكم، لا يسري معدل التغذية على امتداد المسار. الأفضل إدخال القالب «استكمال قطبي تشغيل/إيقاف»",
"{0}: Postprozessor ohne Vorlage „C-Achse und angetriebenes Werkzeug ein“ – C-Achse und Werkzeugspindel von Hand einschalten":"{0}: المعالج اللاحق دون قالب «تشغيل المحور C والأداة المدارة» – شغّل المحور C ومغزل الأداة يدويًا",
"{0}: Postprozessor ohne Zylinder-Interpolation – Z und C fahren gemeinsam, der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Zylinder-Interpolation ein/aus“ eintragen":"{0}: معالج لاحق بدون استكمال أسطواني – يتحرك Z وC معًا؛ وعندئذ، حسب وحدة التحكم، لا يسري معدل التغذية على امتداد المسار. الأفضل إدخال القالب «استكمال أسطواني تشغيل/إيقاف»",
"{0}: Postprozessor ohne {1} für diese Form – als Bahn ausgegeben":"{0}: المعالج اللاحق دون {1} لهذا الشكل – أُخرج كمسار",
