"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"«+» = سيتم إنشاء أداة جديدة. بيانات القطع قيم إرشادية للكربيد ({0}){1}؛ التبريد: {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"يضع خيار “التعشيق المتداخل” قطع القص في الفراغات والتجاويف بين القطع المجاورة وفي فتحاتها (دون تدوير بزاوية 90° ، مع القلب بزاوية 180° فقط)؛ ولا تقل المسافة عن القيمة المحددة أبداً. وبدون علامة الاختيار توضع القطع في صفوف وفق مستطيلها المحيط. يؤدي الخيار “رسم تخطيطي + أجسام” إلى إنشاء أجسام مسطحة بسماكة الصفيحة يمكن قطعها في التصنيع بكفاف ثنائي الأبعاد.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"“داخل/خارج” يحتاج إلى كفافات مغلقة – فرّز المنحنيات المفتوحة بخيار “على المنحنى”",
